def load_grids_from_session():
    """Load grids from the current session using the script from problem statement"""
    import os, glob, re
    d = os.path.normpath(os.environ.get('RLM_SESSION_DIR', ''))
    if not d:
        return {"error": "No session dir"}

    sessions_file = d + '/../../sessions/' + os.path.basename(d) + '.jsonl'
    content = open(sessions_file).read().replace('\\n', '\n')

    G = {}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', content):
        k, h, w = m[1], int(m[2]), int(m[3])
        rows = [r.split() for r in content[m.end():].split('\n')[:h]]
        if k not in G and all(len(r) == w and all(x.isdigit() for x in r) for r in rows):
            G[k] = [[int(x) for x in r] for r in rows]
    return G

