def my_transform(grid):
    """Keep 3s in connected components of 4+ cells, remove the rest"""
    rows, cols = len(grid), len(grid[0])
    result = copy.deepcopy(grid)

    # Find connected components of 3s
    visited = [[False]*cols for _ in range(rows)]
    components = []

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 3 and not visited[r][c]:
                comp = []
                stack = [(r, c)]
                visited[r][c] = True
                while stack:
                    cr, cc = stack.pop()
                    comp.append((cr, cc))
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = cr+dr, cc+dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if grid[nr][nc] == 3 and not visited[nr][nc]:
                                visited[nr][nc] = True
                                stack.append((nr, nc))
                components.append(comp)

    # Remove 3s in components of size < 4
    for comp in components:
        if len(comp) < 4:
            for r, c in comp:
                result[r][c] = 0

    # Now remove 9s adjacent to removed 0-cells (using 8-neighbor on ORIGINAL grid)
    for r, c in [(cu[cu_idx] for cu_idx in range(len(components)) for cu in components[cu_idx] if len(components[cu]) < 4):
        # Find neighbors in 8 directions
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r+dr, c+dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    if grid[nr][nc] == 9:
                        result[nr][nc] = 0

    return result
